import{_ as e,o as a,c as r,a5 as o}from"./chunks/framework.QWVCgkrI.js";const u=JSON.parse('{"title":"手動メモリ管理と GC","description":"","frontmatter":{"title":"手動メモリ管理と GC","study":{"source":"C++ Wiki","status":"published","summary":"C++のRAIIと所有権、C#・UnityのGCと明示的な資源解放を対応させる。","section":"reference","format":"article","domain":"languages"}},"headers":[],"relativePath":"languages/csharp/memory-management-vs-gc.md","filePath":"languages/csharp/memory-management-vs-gc.md"}'),n={name:"languages/csharp/memory-management-vs-gc.md"};function l(s,t,i,d,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="手動メモリ管理と-gc" tabindex="-1">手動メモリ管理と GC <a class="header-anchor" href="#手動メモリ管理と-gc" aria-label="Permalink to &quot;手動メモリ管理と GC&quot;">​</a></h1><p>本論は<a href="/study/runtime/memory/gc-and-csharp-comparison.html">ガベージコレクションとの違い — C#の管理ヒープ・UnityのGC Allocとの比較</a>で詳述済み。このページはUnity開発者の視点からの<strong>要点整理と実践対応表</strong>です。</p><h2 id="「手動」という誤解を先に解く" tabindex="-1">「手動」という誤解を先に解く <a class="header-anchor" href="#「手動」という誤解を先に解く" aria-label="Permalink to &quot;「手動」という誤解を先に解く&quot;">​</a></h2><p>現代のC++ではメモリを解放するたびに手でdeleteを書く代わりに、値とスコープ、RAIIを使って所有と解放を管理します。</p><ol><li>値とスコープで表せる局所的な所有から考えます。値の内部にあるvectorやstring等が動的に確保する場合はあります。</li><li>ヒープが必要ならRAIIとスマートポインタを使い、型が自動で解放できるようにします。</li><li>生のnew/deleteはRAII部品の内部実装に限り、ゲームロジックには出しません。</li></ol><p>「手動」なのは<strong>解放のタイミングと所有権の設計</strong>であって、解放作業そのものではない——ここがC#経験者の第一の発見です。</p><h2 id="実践対応表-unityでの習慣-→-c-での対応" tabindex="-1">実践対応表(Unityでの習慣 → C++での対応) <a class="header-anchor" href="#実践対応表-unityでの習慣-→-c-での対応" aria-label="Permalink to &quot;実践対応表(Unityでの習慣 → C++での対応)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unityでの習慣</th><th>C++での対応</th><th>参照</th></tr></thead><tbody><tr><td>GC Allocをプロファイラで監視</td><td>ヒープ確保をプロファイラ/自作カウンタで監視</td><td><a href="/study/runtime/memory/allocators-and-pools.html">アロケータ</a></td></tr><tr><td>Update内でnewしない</td><td>フレーム内のヒープ確保を避ける(値・再利用・アリーナ)</td><td>同上</td></tr><tr><td>オブジェクトプール</td><td>Object Pool(同じ)+ memory pool</td><td><a href="/study/game/patterns/object-pool.html">Object Pool</a></td></tr><tr><td>structの利用 / NativeArrayの利用</td><td>値型の表現を選ぶことと、ネイティブ領域を明示管理することを分ける。structだけで管理外やスタック配置にはならない</td><td><a href="/study/languages/csharp/pointers-references-value-semantics.html">値セマンティクス</a></td></tr><tr><td>不要な強い参照を手放す</td><td>C++では所有者の破棄がオブジェクト破棄や記憶域返却へつながる。OSへの返却は別。非所有参照は寿命を延ばさない</td><td><a href="/study/runtime/memory/ownership-and-borrowing.html">所有権</a></td></tr><tr><td>Destroyによるネイティブ側の破棄</td><td>C++でも、破棄後の非所有参照を使う問題と、所有者による破棄を分ける。未定義動作は通常の例外処理で回復できる契約ではない</td><td><a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a></td></tr><tr><td>WeakReference(ほぼ使わない)</td><td>weak_ptr/世代ハンドル(<strong>日常の道具</strong>)</td><td><a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a></td></tr></tbody></table><h2 id="思考の転換ポイント3つ" tabindex="-1">思考の転換ポイント3つ <a class="header-anchor" href="#思考の転換ポイント3つ" aria-label="Permalink to &quot;思考の転換ポイント3つ&quot;">​</a></h2><ol><li><strong>確保・破棄・回収を分けて測る</strong>: 両環境とも、再利用だけで済む経路と、領域の補充・回収・初期化などが必要な経路があります。言語名だけで速度を決めず、頻度・サイズ・寿命・フレーム時間をそろえて測ります。</li><li><strong>参照・所有・到達可能性を区別する</strong>: 通常の安全な管理参照を通じた利用はGCが扱い、C++の生ポインタや参照は通常非所有です。C#でも字句スコープだけが生存保証ではなく、unsafe・ネイティブ資源の寿命は別に考えます。</li><li><strong>リークの形が変わる</strong>: C#のリークは「参照の残留」(イベント購読・static)。C++のリークは「所有者の不在」(生new・循環shared_ptr)。<strong>どちらも設計の失敗</strong>であり、GCはそれを免除しない</li></ol><p>根拠となる<a href="https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/builtin-types/value-types" target="_blank" rel="noreferrer">C#の値型</a>と<a href="https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/fundamentals" target="_blank" rel="noreferrer">.NETのGCのルート・生存情報</a>も参照してください。OS側は<a href="/study/runtime/memory/allocation-journey.html">malloc/newの内部</a>へつながります。</p><h2 id="実務でのハイブリッド感覚" tabindex="-1">実務でのハイブリッド感覚 <a class="header-anchor" href="#実務でのハイブリッド感覚" aria-label="Permalink to &quot;実務でのハイブリッド感覚&quot;">​</a></h2><ul><li>UnityでもDOTS/NativeArrayを使えば「手動管理の世界」に半分入っていた(Allocator.Temp/Persistent、Dispose必須)——あれがC++の日常</li><li>UEに行くと「C++なのにUObjectはGC管理」という逆ハイブリッド(→ <a href="/study/game/unreal/gc-and-object-pointers.html">UEのガベージコレクションと UPROPERTY・TObjectPtr・TWeakObjectPtr</a>)</li><li><strong>どの言語・エンジンでも「寿命のパターンを見つけて構造化する」のが本質</strong>で、道具(GC/RAII/プール)はその実装手段</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>「C++は手動メモリ管理」という表現のどこが不正確ですか。</li><li>C#とC++で「参照を持つ」の意味はどう違いますか。</li><li>両言語のリークの典型形を1つずつ挙げてください。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><a href="/study/runtime/memory/exercises.html">メモリと実行時の演習</a>の問4(当たり判定結果の一時データ)を、Unity C#で同じ問題を解く場合(List再利用/NativeArray+Temp)と対比しながら解いてください。「同じ問題に同じ答え(再利用)を出している」ことの確認が目的です。</p><hr><p>関連項目：<a href="/study/languages/csharp/il2cpp.html">ネイティブビルドとIL2CPP</a> / <a href="/study/languages/csharp/">学習ガイド</a> / <a href="/study/languages/csharp/exceptions-comparison.html">C++例外とC#例外</a></p>',19)])])}const p=e(n,[["render",l]]);export{u as __pageData,p as default};
